INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:1','mayalex_normativos','10_LEYES_REGLAMENTOS','Para todos los efectos de este Código, se entenderá por niño o niña a todas las personas hasta los dieciocho (18) años de edad.

Las disposiciones contenidas en este Código son de orden público y los derechos que establecen en favor de los niños y niñas son irrenunciables, intransigibles y de aplicación obligatoria en todo acto, decisión o medida administrativa, judicial o de cualquier naturaleza que se adopte respecto de las personas hasta los dieciocho (18) años de edad, las que para todos los efectos legales se considerarán como niños y niñas.

En caso de duda sobre la edad de un niño o niña, se presumirá mientras se establece su edad legal efectiva, que es menor de dieciocho (18) años.','1','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":1,"article_sha256":"7f836df1223cfeb3bdf40194af0d5ed4c9761e7a796ce1bc0bd16461a26ed2d4","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','1','beef781067bf9acbbff83df4631301e41d34e4ebb51e9fef6ee904785114c278','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:6','mayalex_normativos','10_LEYES_REGLAMENTOS','El Gobierno de la República, por medio de los organismos que más adelante se determinarán, velará por el estricto cumplimiento de los derechos de los niños establecidos en este Código y en los tratados o convenios internacionales de los que Honduras forme parte.

Con tal fin, adoptará las medidas económicas, sociales y culturales que sean necesarias para brindarle apoyo a la familia y a la comunidad, con miras a crear condiciones que hagan posible el sano y pleno desarrollo de los niños.','6','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":6,"article_sha256":"8f18ac4b4d4e16f60bbd954170ea72cd44618479bc6cc26ec4a5037883bea7ac","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','6','a07b60b8b24972cc477b9cd1c077a3d5a7dbb15ea0560dfb8bf23c137dcde20b','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:8','mayalex_normativos','10_LEYES_REGLAMENTOS','Las decisiones que el Gobierno adopte en relación con la niñez deben hacer posible la actuación armónica y complementaria de los sectores público y privado.','8','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":8,"article_sha256":"88a96049cce13ac3efcb3499d78f5f4fc3db18ba1f276bd068e66e69e86555b9","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','8','4830902d88b8fa89e64a06bb80b0a779b64dcc9ddce512eb751db23c91439d94','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:27','mayalex_normativos','10_LEYES_REGLAMENTOS','Los niños gozan de las libertades consignadas en la Constitución de la República, en los convenios internacionales de que Honduras forme parte y en el presente Código.','27','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":27,"article_sha256":"2cfead23d5be4251e259dee8eae8fe79ec5c432f1244029cdbd837e214fc1fed","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','27','f0c8f5c16f85c9230f67fe69c2541165548ffd5f55abedab0bfbf92ad7a42f4c','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:31-A','mayalex_normativos','10_LEYES_REGLAMENTOS','El Estado, por medio del Instituto Hondureño de la Niñez y la Familia (IHNFA), implementará un programa de prevención de la migración irregular de niños y niñas, que asegure la protección de sus derechos, su

identificación y documentación y en su caso, la de sus representantes legales; y facilite su reintegro a su medio familiar y su centro de vida.','31-A','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":32,"article_sha256":"43d8d06d7bcfe8559ffc497ab688669a2159cde8c6eeb860ee07d5e1ed0d416d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','31-A','178efe1cec5c8097173ec0a8b587a45ad2557edac8302a72bc89f681ba5d5ce5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:33','mayalex_normativos','10_LEYES_REGLAMENTOS','En los casos a que se refiere el artículo precedente, el Juzgado de la Niñez o el que haga sus veces, podrá ordenar la suspensión de la publicación, reproducción, exposición, venta, distribución o acto de que se trate, hasta que se establezca su licitud o se resuelve, en definitiva.','33','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":35,"article_sha256":"faa74e142b6e36f06894d98a27b2dbb6674e57807323bedc52ee7e436df50d5e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','33','138dd313ef0c762c87d49a1c790827f978a884a0f1432c1ddb95ceb0c8c3cbd8','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:49','mayalex_normativos','10_LEYES_REGLAMENTOS','El Consejo Nacional de la Juventud, dependiente del Congreso Nacional, colaborará con la Secretaría de Estado en los Despachos de Cultura y las Artes para promover, financiar y supervisar la formación de asociaciones de niños que tengan como finalidad investigar y divulgar las tradiciones nacionales.','49','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":51,"article_sha256":"823809dd00e6d7a8a57a4df16560f8f1139d33a6b62b374341f0d16640834a9e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','49','6dab6d68043d36c12a59255ac86a27a9a928168611daba6ff5e22fe70b4dcabb','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:50','mayalex_normativos','10_LEYES_REGLAMENTOS','Los niños tienen derecho a conocer la información proveniente de fuentes nacionales y extranjeras compatible con lo dispuesto en este Código, en particular aquella que tenga como finalidad promover el bienestar social, espiritual y moral de las personas o su salud física o mental. Tienen derecho, igualmente, al respeto de sus formas culturales. Para hacer efectivos estos derechos el Estado:

a) Requerirá a los medios de comunicación social la difusión de informaciones y materiales de interés social y cultural dirigidos a la niñez.

b) Promoverá la producción, difusión y lectura de literatura infantil y juvenil.

c) Estimulará a los medios de comunicación para que produzcan y difundan programas de interés social y cultural acordes con las necesidades lingüísticas de los niños, en especial para aquellos que pertenezcan a grupos étnicos autóctonos y garífunas.

ch) Controlará, por medio de las Secretarías de Estado en los Despachos de Educación Pública y de Cultura y las Artes, así como el Instituto Hondureño de la Niñez y de la Familia (IHNFA), el contenido de los materiales destinados a la niñez y adoptará medidas para que se difundan en horarios especiales; y, d) Velará porque no circulen entre los niños libros, folletos o escritos de cualquier clase, afiches, propaganda, videos, programas de televisión o de computación u otros medios visuales o audiovisuales en los que figuren imágenes o contenidos pornográficos o que promuevan la violencia o el desconocimiento de los derechos de aquellos. La violación de esta norma será sancionada con multa hasta de cien mil lempiras (L. 100,000.00).','50','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":52,"article_sha256":"10f8ce9e3003bc5853049fd7de95f7a44926ac6f69bfada34ec5390ea43fe5e2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','50','d37c945cb7da745f0078698e2898989a0334f8af253441c184e325712818a487','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:54','mayalex_normativos','10_LEYES_REGLAMENTOS','- Los niños tienen derecho a gozar de un ambiente sano y al conocimiento y buen uso de los recursos naturales.','54','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":56,"article_sha256":"88d8ffd2515203f37441170d2b21e3fe60a6d44c0f936483f74f624c7c077b78","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','54','7c1a166ca9fd85af49075f5dd6b02469b2498558018fb205232bb846d11f060e','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:68','mayalex_normativos','10_LEYES_REGLAMENTOS','[DEROGADO — art. 11 del Decreto No. 35-2013]','68','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":70,"article_sha256":"78aa884350ef9d24ba3c8957c07830f66446e57b23a9c0ef1493010bed536948","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"DEROGADO","fuente_canonica":"D35_2013_ART_11"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','68','41aca8e8f4023d8844642c3da7b7623d352b51bafe506246c7ac29c141fdfa1d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:85','mayalex_normativos','10_LEYES_REGLAMENTOS','Todos los asuntos relacionados con la niñez serán confidenciales, por lo que el contenido de los respectivos expedientes sólo podrá ser conocido por las partes y por los empleados o funcionarios directamente involucrados en su tramitación.

Sólo a petición de los representantes legales y de las autoridades competentes se extenderán constancias o certificaciones sobre las aprehensiones y procedimientos relacionados con niños.

Los medios de comunicación se abstendrán de hacer publicaciones de cualquier clase sobre la participación que haya tenido un niño en actos ilícitos, bien sea como sujeto activo o pasivo.

Quienes violen lo dispuesto en este artículo serán sancionados en la forma prevista en el artículo 32, precedente.','85','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":87,"article_sha256":"0014addf028371675c79162515c681333f9502932c69d7e41fbfd9cdfb0b4124","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','85','139388b086cab3aa7085596adf75005fe4724de5f55f9fa5b404e9a1da342ddc','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:99','mayalex_normativos','10_LEYES_REGLAMENTOS','Quien contravenga lo dispuesto en los artículos 97 y 98 de este Código, será sancionado de acuerdo a las reglas siguientes:

1. Multa de veinte (20) a treinta (30) salarios mínimos en su valor más alto, en la categoría que determine la Ley de Salario Mínimo, si es por primera vez; 2. Suspensión de su permiso de operaciones hasta por dos (2) semanas, si es por segunda vez; y, 3. Cancelación de su permiso de operaciones, si es por tercer vez.

Tales sanciones serán impuestas por la autoridad que haya expedido los permisos de operación.

El importe de las multas establecidas en este Artículo será enterado en la Tesorería de las Alcaldías Municipales, dentro de los cinco (5) días hábiles siguientes al de su notificación quedando obligado el(a) infractor(a) a presentar el recibo de pago a la autoridad que le impuso la sanción, dentro de los tres (3) días siguientes. La Municipalidad respectiva debí

de utilizar estos fondos en programas y proyectos destinados a la niñez.','99','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":101,"article_sha256":"aa52b961f97b427e0d89a1038333dc104440ff3935df519c7f9ed00c999346b7","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','99','4e47d1339d88e348aeab728c9bbde7a9c6b395c52aa2527aedb40a007112f07e','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:101','mayalex_normativos','10_LEYES_REGLAMENTOS','Los niños sólo podrán salir del país si van acompañados de su padre, de su madre o de su representante legal o, en defecto de éstos, de la persona que cuente con la respectiva autorización escrita.

Si la patria potestad la ejercen ambos padres, se requerirá la autorización escrita del otro si sólo uno acompañara al niño durante el viaje.

Las correspondientes firmas deberán ser autenticadas por Notario.','101','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":104,"article_sha256":"9a9f0c80509f8a46577fa069afcf18e73a053738f30510454feb3d77f48b14be","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','101','80d0559215d80a57aaeb026733c27b6fe928ab359ca996bfea8c4ce13632e285','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:104-A','mayalex_normativos','10_LEYES_REGLAMENTOS','Presentada la solicitud, el(la) Juez(a) citará en legal y debida forma a la parte contraria, para que dentro del término de tres (3) días siguientes a la fecha de la citación, comparezca a una audiencia en la que se conocerá el asunto breve y sumariamente, debiéndose dictar sentencia en la misma o a más tardar al día siguiente. Contra dicha resolución cabrán los recursos de reposición y apelación subsidiaria.

La oposición deberá resolverse en la misma audiencia.

Las partes deberán presentarse a la audiencia, con las pruebas en que sustenten sus argumentaciones.

La Cédula de Citación deberá ser acompañada de la copia de la solicitud respectiva.

En caso de no cumplimentarse la citación por no ubicarse a la persona citada, el(la) Juez(a) resolverá de conformidad'' con las pruebas que acompañen la solicitud, en el término de tres (3) días, sin la realización de la audiencia.','104-A','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":109,"article_sha256":"f5ebf524a33f8f039472fd29b46b8016c98a159a3e3e4e5ce2a36e9ac0f2a0b9","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','104-A','00aae460146a051fbe465b96de0184fd14ad56cf047e2beb91dac6dee22f8a20','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:123','mayalex_normativos','10_LEYES_REGLAMENTOS','Queda prohibido a los niños menores de dieciocho (18) años todo trabajo que afecte su moralidad. En especial les está prohibido el trabajo en casas de lenocinio y demás lugares de diversión donde se consuman bebidas alcohólicas.

Es también prohibida su contratación para la reproducción de escenas pornográficas, muertes violentas, apología del delito u otras labores semejantes.','123','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":128,"article_sha256":"bc1f63a2972e97cdaf44c9af75ca7a5fe494aefa12211f97c19eb9002b35ae3b","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','123','7bd5858856eb3b1b5b1cf56d5c97944e127918c40e0d4e5614ad43c9fbca68b8','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:128','mayalex_normativos','10_LEYES_REGLAMENTOS','La Secretaría de Estado en los Despachos de Trabajo y Seguridad Social inspeccionará regular y periódicamente a las empresas, centros y lugares de trabajo y casas de habitación y en este último caso, previa autorización judicial cuando éste sea su centro de trabajo, para verificar si tienen a su servicio niños y niñas y si están cumpliendo las normas que los protegen.

Quién transgreda dichas normas será sancionado(a) con multa de cinco (5) a quince (15) salarios mínimos en su valor más alto. La reincidencia será sancionada con el doble de la multa anterior.

Cuando se haya puesto en peligro la vida de un niño o niña o se haya atentado contra su dignidad, integridad física, psíquica o intelectual, además de la multa prevista se le aplicarán las sanciones civiles y penales a que haya lugar.','128','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":133,"article_sha256":"216c2a686b663eb53d3d8cc33299c9dc54a70379941c0f5435868a527c0a91e7","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','128','4c8f8e7037efd5a789eb0055937ad5a2da7a0420c2db4d92473a6dbedeb5d7e6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:129','mayalex_normativos','10_LEYES_REGLAMENTOS','Por medio del contrato de aprendizaje un niño se obliga a trabajar para un patrono por un salario determinado a cambio de que el segundo le provea la formación técnica-profesional que requiera para aprender un oficio, arte o industria.','129','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":134,"article_sha256":"821e256aeba038fbc07decc3937c025be29b005de994584d6cc40cb95bb94c1a","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','129','b8d49d6d920abe7d0afffb4cf7fab069333f46f26d64971cf420611501f5fd63','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:132','mayalex_normativos','10_LEYES_REGLAMENTOS','El Contrato de aprendizaje será siempre remunerado. La remuneración no podrá ser inferior al salario mínimo.

Si concluido el aprendizaje la relación laboral continua, el aprendiz adquirirá el carácter de trabajador y gozará de todos los derechos y prestaciones derivados de los contratos de trabajo, salvo que la Secretaría del Estado en los Despachos de Trabajo y Seguridad Social disponga otra cosa habida cuenta del desarrollo del niño, de su estado de salud o de la naturaleza de las labores que deba cumplir.

Para los efectos legales de los mencionados contratos, se entenderán iniciados desde que comenzó el aprendizaje.','132','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":137,"article_sha256":"134d0b217973e326d18d967964048fa209fd39cd517021699c025a17b3d46460","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','132','575b7d97da279780bfd0b0add5da93540a70ab0b8211efd78ecd6294b42ab75a','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:141','mayalex_normativos','10_LEYES_REGLAMENTOS','Un niño o niña se encuentra en situación de abandono, cuando:

a) Fuere abandonado en lugares públicos; b) Falten en forma absoluta las personas que conforme a la Ley, tienen el cuidado personal de su crianza educación; y, c) No sea reclamado por sus padres o representantes legales al ser dado de alta, en establecimientos hospitalarios o de asistencia social.','141','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":146,"article_sha256":"3639d4570face98da5e7e57448061893344e2f8fd6c901f98a64d19c38395c46","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222","observaciones_canonicas":["Texto reformado (a–c); el art. 11 del D.35-2013 deroga los literales ch)–f) del 141 original (resolución del CLO 2026-11-18)."]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','141','0d0809b91d6dc010ebdcc9a68fd6f9bf753116c47531e658ba5cdd90b5b13514','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:146','mayalex_normativos','10_LEYES_REGLAMENTOS','A los(as) responsables de incumplimiento de lo establecido en los artículos 143, 144 y 145 precedentes se les sancionará con multa de cinco (5) a quince (15) salarios mínimos en su valor más alto, la que impondrá el titular de la institución a quien corresponda. La indicada multa se aplicará sin perjuicio de la responsabilidad civil y penal a que hubiere lugar en Derecho.

Para la deducción de estas responsabilidades, se informará y al Ministerio Público sobre los hechos de que se trate, cuando éstos sean constitutivos de delito.','146','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":151,"article_sha256":"56b0b93a3778e5813419386863ba1600eb3d525a9f4f9aaebfd7474a09ec91d2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','146','38d605b8de24d8b62769076a0f8cebc91d3aa6fd8a49c4cd86b6c0562245c8c4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:147','mayalex_normativos','10_LEYES_REGLAMENTOS','Corresponde al Instituto Hondureño de la Niñez y la Familia (IHNFA), conocer, investigar y determinar la existencia de causales de las situaciones de abandono y de incumplimiento de derechos de la niñez en sede administrativa. El Instituto Hondureño de la Niñez y la Familia (IHNFA) actuará de oficio o a petición de cualquier persona, debiendo emitir auto motivado con las pruebas y argumentos presentados, en el que declarará admitida o desestimada la solicitud o archivadas las diligencias, según sea el caso.

Si admite la solicitud o actúa de oficio, adoptará las medidas de protección que sean necesarias y citará a una audiencia con la participación del padre, madre o representante legal, si se conociera su paradero, en su defecto citará a cualquier persona bajo cuyo cuidado haya estado el niño o niña de que se trate. Tal audiencia se realizará en el término de cinco (5) días contados a partir de la fecha del auto en que se dio inicio el procedimiento. Si se desconoce el paradero de los padres o representantes legales el término será de ocho (8) días, ordenándose en el auto con que se dio inicio el proceso que se realicen tres (3) publicaciones en dos (2) diarios escritos, hablados o televisivos de circulación nacional, incluyendo la fotografía del niño o niña o señas particulares, según el caso.

La denuncia de abandono podrá ser presentada verbalmente o por escrito, por cualquier persona natural o jurídica, debiendo contenerlo siguiente:

1) Nombre del niño o niña si se supiere y en su defecto señas particulares del(a) mismo(a); 2) Nombre de los padres o representantes legales o de la persona a cuyo cargo estaba o está el niño o niña, si se supiere y en su defecto señas particulares del mismo; 3) Lugar en que se encontró o se encuentra el niño o niña; y, 4) Otro dato que sea de interés para la protección del niño o niña.','147','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":152,"article_sha256":"928bd0cd95fbe17889b916028c3b530d0e45be1341482f15fbe11be4de63fcba","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','147','af8e4f1f1607d1164ac1031588515f801b78450174e8167cd2c959e5c5b8d880','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:151','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto hondureño de la Niñez y la Familia, con el objeto de asegurar la adecuada atención al niño en el seno de su familia, podrá disponer, si lo cree conveniente, que los padres o el representante legal a cuyo cuidado se encuentre, cumplan alguna de las actividades siguientes:

a) Asistir a programas oficiales o comunitarios de orientación o tratamiento familiar.

b) Asistir a programas de asesoría, orientación o tratamiento de alcohólicos o adictos a sustancias que produzcan dependencias, cuando sea el caso.

c) Asistir a programas de tratamientos sicológico o siquiátrico; o, ch) Participar en cualquier otra actividad que contribuya a garantizar un ambiente adecuado para el desarrollo del niño.','151','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":161,"article_sha256":"7d6d91c8bb5283f6847e74f43e08d3aa62b89902db3b935a2316639872e25d70","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','151','2f837d2b1c9b9f3d1b0690a7df3f158adbc23a067c2025511b8aad91f3b3fcbc','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:156','mayalex_normativos','10_LEYES_REGLAMENTOS','Las medidas de protección al niño que se encuentre en la situación prevista en esta sección serán adoptadas a solicitud de sus padres o representante legal, o de oficio.

Las medidas procurarán apoyar a los solicitantes, en su caso, y no separar al niño de su medio familiar.

En el cumplimiento de sus cometidos al Instituto Hondureño de la Niñez y la Familia podrá:

a) Asesorar al respectivo padre, madre o representante legal para que pueda obtener alimentos de las personas llamadas por este Código y el Código de Familia a cumplir dicha obligación; o, b) Vincularlo a los programas que en beneficio de los niños desarrolle ella misma u otros organismos públicos o privados.','156','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":166,"article_sha256":"cb65c0dc5a10034053f41862ab62d82f142a7c8c63f793a178d59e3e3600d745","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','156','a1e1afae837bb63680b5146264423a608f29cd32970ec04b5876233ddb11e775','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:167','mayalex_normativos','10_LEYES_REGLAMENTOS','El Estado, por medio del Instituto Hondureño de la Niñez y la Familia (IHNFA) formulará y pondrá en práctica programas de detección, registro y seguimiento de los niños y niñas que hayan sido maltratados, así como de quienes hayan sido agresores y demás víctimas.','167','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":177,"article_sha256":"57560d85b10f637169947992f2553e61c17516078ce1a06f202fa79c4ef996be","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','167','42fabc2dcf90be0550d70d3d3d0c956df819f0c8c0043e656185294a0870b4b5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:171','mayalex_normativos','10_LEYES_REGLAMENTOS','[DEROGADO — art. 11 del Decreto No. 35-2013]','171','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":181,"article_sha256":"2c50ed08aadfbb75573a5ae9b7d26301b6553ca36a5e12f661e60562aaff720e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"DEROGADO","fuente_canonica":"D35_2013_ART_11"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','171','41aca8e8f4023d8844642c3da7b7623d352b51bafe506246c7ac29c141fdfa1d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:173','mayalex_normativos','10_LEYES_REGLAMENTOS','Quien cause maltrato a un(a) niño(a) sin llegar a incurrir en los delitos o faltas previstas por el Código Penal, será sancionado(a) con multa que oscilará entre medio (112) a dos (2) salarios mínimos en su valor más alto, sin perjuicio de las medidas de protección que adopte él Instituto Hondureño de la Niñez y la Familia (IHNFA).

Para los efectos de este Artículo, se considera maltrato a un niño cuando se le hace víctima de violencia física o psíquica, explotación, o cuando se le obliga a cumplir actividades que impliquen riesgos para su salud física o mental o para su condición moral o que impidan su concurrencia a los

establecimientos educativos y/o interfieran o amenacen su desarrollo físico, psíquico y social.

Sin perjuicio de las penalidades establecidas para el(la) autor(a) de maltrato infantil y las impuestas por el Código Penal, todo niño o niña que resultare víctima de abuso sexual, explotación sexual en espectáculos pornográficos, turismo sexual, trata de personas, u otras prácticas sexuales ilegales, recibirá atención médica, psicológica y/o psiquiátrica por parte del Estado, a través del Instituto Hondureño de la Niñez y la Familia (INHFA), en el marco de un Programa orientado a lograr la prevención y rehabilitación de niños(as) víctimas.','173','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":183,"article_sha256":"d583e8bf2a52e23f28f07d9233665fb21c20ae74e8b8774b7012b988af8c2a38","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','173','b7b39dd9bc93ccc28614bd5ad305f866f32848285e474959c4eceafa0dacccc4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:174','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto Hondureño de la Niñez y la Familia, o el Ministerio Público serán parte en los procesos que se adelanten por los hechos punibles previstos en esta Sección. Con tal fin, el juzgado correspondiente les notificará lo pertinente.','174','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":184,"article_sha256":"ddad4ff7bc848a0c37666472719b6bf71984c2972f0c9ad79daed8331d8bfda6","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','174','eabecf66e4284b7056d808b0d293d297bc1a4c7c8bf43d268e8a069fe7434392','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:180-B','mayalex_normativos','10_LEYES_REGLAMENTOS','Sin perjuicio de otros contenidos en este Código, son principios rectores de El Sistema, los siguientes:

a) Interés Superior; b) Formación Integral; c) Reinserción en su Familia y en la Sociedad; d) Justicia Especializada; e) No Discriminación; f) Legalidad; g) Lesividad; h) Humanidad; i) Confidencialidad; j) Racionalidad, Proporcionalidad y Determinación de las Medidas y Sanciones para Niños(as); k) Excepcionalidad; I) Oportunidad; y, m) Justicia Restaurativa.

A tal. efecto, se entenderá por:

INTERÉS SUPERIOR: Sin perjuicio y en concordancia con lo dispuesto en el Artículo 5 de este Código, El Sistema estará dirigido a asegurar el pleno y efectivo ejercicio y disfrute de todos los derechos y garantías de El Niño(a).

FORMACIÓN INTEGRAL: Toda actividad estará dirigida a fortalecer el desarrollo personal de El Niño(a), el respeto por su dignidad, derechos fundamentales de todas las personas y su función constructiva en la sociedad.

REINSERCIÓN DE EL NIÑO(A) EN SU FAMILIA Y EN LA SOCIEDAD: Toda actividad estará dirigida a garantizar el ejercicio pleno de los derechos de El Niño(a), en el seno de su comunidad y de su familia, conforme a las previsiones de este Código. En lo posible, dentro del marco de la Justicia Juvenil Restaurativa.

JUSTICIA ESPECIALIZADA: Desde el inicio del Proceso, todas las actuaciones y diligencias estarán a cargo de órganos especializados.

NO DISCRIMINACIÓN: Implica que los derechos y garantías reconocidos en este Código, se aplicarán sin discriminación alguna por razones de orientación sexual, origen étnico, social, índole económica, religión o cualquier otro motivo semejante, propio o de sus padres, familiares u otras personas responsables o que los tengan bajo su cuidado.

LEGALIDAD: Ningún Niño(a) debe ser procesado ni Sancionado por actos u omisiones que, al tiempo de ocurrir, no estén tipificados como Hecho Delictivo o Falta.

LESIVIDAD: El Niño(a) no debe ser objeto de sanción, si su conducta no lesiona o pone en peligro un bien jurídico tutelado.

HUMANIDAD: Ningún Niño(a) debe ser sometido a torturas, tratos o penas crueles, inhumanos o degradantes, ni a métodos o técnicas que induzcan o alteren su libre voluntad, su estado consciente o atenten contra su dignidad.

CONFIDENCIALIDAD: Son confidenciales los datos sobre los hechos cometidos o supuestamente cometidos por El Niño(a). En todo momento, debe respetarse su identidad e imagen. El Juez garantizará que la información que se brinde sobre estadísticas judiciales, no contravenga este principio ni el derecho a la intimidad.

RACIONALIDAD. PROPORCIONALIDAD Y DETERMINACIÓN DE LAS MEDIDAS Y SANCIONES: Las medidas y sanciones que se impongan a El Niño(a), deben ser racionales y proporcionales a la infracción cometida o supuestamente cometida y adecuadas a las circunstancias en que se encuentre el infractor o supuesto infractor. No pueden imponerse medidas o sanciones indeterminadas.

EXCEPCIONALIDAD: La privación de libertad tiene carácter excepcional y se aplicará únicamente por el tiempo determinado en este Código.

OPORTUNIDAD: Consiste en el beneficio de la abstención total o parcial del Ministerio Público del ejercicio de la acción penal o la facultad de limitarla a una o varias de

las infracciones, mediante la aplicación de medidas alternas ..al juicio.

JUSTICIA RESTAURATIVA: Es un principio general del proceso penal para infractores de la Ley, que promueve la inclusión de los valores de respeto, responsabilidad y transformación de relaciones, en todos los procesos en que intervenga un Niño(a), con el propósito de brindarle apoyo en su acto voluntario de responsabilizarse por sus acciones y efectos dañinos, a través del diálogo respetuoso con la persona ofendida, familiares y personas de su entorno comunitario, para encontrar en conjunto la manera de enmendar y corregir el mal causado. Este principio podrá ser aplicable, mediante la posibilidad de referir las diligencias instadas a programas de Justicia Restaurativa, creados fuera de El Sistema o en colaboración con éste.','180-B','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":192,"article_sha256":"4a60645bf597dccf7efa66cd0ae2659fb3e43152c47a526246d8cc3ba712b423","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3_ADICIONADO","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','180-B','261df4db98b1757de65497dd5f28ed2d954bc8961ddbc90e8837f1e7500a889c','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:181','mayalex_normativos','10_LEYES_REGLAMENTOS','Se garantiza que todo Niño(a) gozará del pleno respeto de los derechos y garantías establecidas en la Constitución de la República, los Tratados y Convenios internacionales vigentes en Honduras, este Código y demás leyes relacionadas con la materia. Especialmente los siguientes:

a) No ser aprehendido, sino en virtud de orden de Juez competente, salvo los casos de flagrancia dispuestos por la Ley, conforme a las disposiciones especiales de este Código; ser informado directamente, sin demora y en forma clara y precisa sobre la causa de su aprehensión, la autoridad que la ordenó y solicitar la presencia inmediata de sus padres, tutores o representantes legales; b) Contar con la asistencia técnica de un Profesional del Derecho, desde su aprehensión o presentación voluntaria, al momento de rendir la respectiva declaración, en su caso, y en cualquier etapa del Proceso, hasta que la sentencia haya sido plenamente ejecutada; c) Comunicación efectiva inmediatamente a su aprehensión, vía telefónica o por cualquier otro medio, con su familia, referente afectivo, defensor o a quien éste desee informar sobre tal hecho y, en su defecto, se informe al Instituto Hondureño de la Niñez y la Familia (IHNFA) para que tutele sus derechos; d) Ser presentado al Ministerio Público o en su caso al Juez competente, sin demora y en él plazo legal establecido, así como a no ser conducido o aprehendido en forma que dañe su dignidad o se le exponga al uso de la fuerza, salvo que exista peligro inminente de fuga o riesgo de daño a la integridad de terceros;

e) Participar en el Proceso, ser oído y a que su opinión sea tomada en cuenta en cualquier fase del mismo; que se permita la plena participación de sus padres, representantes legales o el que haga sus veces, salvo que sea contrario a su Interés Superior. Para tales efectos, de no poderse comunicar por sí mismo, a que se le nombre traductor o intérprete idóneo; f) Tener identificación personal o a que se le provea una, en caso de faltarle; g) Ser juzgado por un Juez natural, imparcial, independiente, especializado y, que el Proceso sea conocido por Jueces diferentes, de conformidad a este Título; h) Se respete, en todo procedimiento, los principios de oralidad, contradicción, concentración, continuidad, celeridad y reserva; i) Solicitar al Ministerio Público, por medio de sus representantes, que ejercite las acciones pertinentes para deducir responsabilidad a los funcionarios y empleados judiciales, administrativos o de cualquier otro orden, que hayan abusado de su autoridad o vulnerado sus derechos; j) Impugnar cualquier resolución provisional o definitiva que le afecte, conforme a este Código; k) Se garantice la confidencialidad y uso de los registros administrativos y judiciales que se lleven sobre su sujeción a El Sistema. En consecuencia, queda prohibida la emisión de certificados o constancias de registros policiales o judiciales penales relacionados con las denuncias y los procedimientos en trámite o sobre la ejecución de sanciones, salvo los necesarios para los fines del Proceso; y, 1) En el caso de las mujeres embarazadas y lactantes que se les brinde la atención especial que requiere tal condición.','181','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":193,"article_sha256":"657e2330078ea2446110aa7365768a6ab3536c2eb5adaa42f268c28ca5cd850e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','181','d8f19de49e6b4b864e66d80536421e0801e4d8801d1a27dc258a15f5ce806c41','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:188','mayalex_normativos','10_LEYES_REGLAMENTOS','Serán de aplicación al Proceso, las Medidas Cautelares previstas en el Artículo 173 del Código Procesal Penal, con excepción de las reguladas en los numerales 1), 2), 10) y 12), en todo cuanto no esté regulado en este Título.

Las Medidas Cautelares serán impuestas mediante resolución judicial motivada, deberán ser proporcionales a la infracción y adecuadas a las circunstancias en que se encuentre El Niño(a). Estas serán aplicadas por los períodos más breves posibles, pero no excederán los seis (6) meses.

En todos los casos, el Fiscal fundamentará la solicitud de Medidas y, mediante auto motivado, el Juez resolverá lo procedente conforme a Derecho.','188','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":201,"article_sha256":"63238e6d0319d5fe21cd3cca4ace5a353e9da9abc7f4949bd3d3a7e515980f4c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','188','80197b6162acadbca5faaf0a799e6916dc1f9660220572b95736f6cbead6589b','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:190','mayalex_normativos','10_LEYES_REGLAMENTOS','La aprehensión de El Niño(a) será hecha de conformidad con las disposiciones, principios, derechos y procedimientos consignados en la Constitución de la República, el presente Código y demás leyes aplicables.

Ningún Niño(a) podrá ser aprehendido sin orden escrita de Juez competente, salvo el caso de flagrancia o fuga de un centro especializado de internamiento en el que estuviera cumpliendo una Medida Cautelar o Sanción.

El Ministerio Público lo pondrá a la orden del Juez competente, dentro de las veinticuatro (24) horas siguientes a su detención.

Quienes realicen la aprehensión deberán identificarse y mostrar la orden judicial que los autoriza para ejecutarla, en su caso, además deberán reducir al mínimo el uso de la fuerza u otro medio que pueda ocasionarle daño.

El uso de la fuerza, así como de cualquier otro medio para la aprehensión serán los adecuados a su condición y no podrán atentar contra su dignidad. Queda prohibido el uso de esposas, ataduras o medios de sujeción que atenten contra su dignidad, salvo que exista peligro inminente de fuga o que se cause daño o se le pueda causar a otras personas. Si es necesario el uso de armas, deberá preferirse la incapacitantes no letales.','190','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":203,"article_sha256":"da015b12f0c4866833259f3fd59f882b379a4c3cc6c8705c28141f400336e699","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','190','ea1a14a976e0200b4a1cb2c34e843e699dcf2dfd45e0014b9ca3b3f7717dea86','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:202','mayalex_normativos','10_LEYES_REGLAMENTOS','La Privación de Libertad Domiciliaria consiste en el arraigo del Sancionado a su domicilio y con su familia.

De no poder cumplirse en su domicilio, se practicará en la casa de cualquier familiar y, en su defecto, podrá ordenarse en una vivienda o en centro estatal, de comprobada idoneidad.

Esta no debe afectar el cumplimiento del trabajo, ni la asistencia al centro educativo a que concurra el Sancionado.

No será menor a uno (1) ni superior a nueve (9) meses.','202','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":215,"article_sha256":"6e5ff16c838ee47abed4f7df77f823b0c3bc70850b5e330219c69b2b04161145","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','202','2750da80803e2addec9384ff920b5e24f157e9322e74073b4d549dcb2398edb6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:205','mayalex_normativos','10_LEYES_REGLAMENTOS','La Privación de Libertad en un Centro Estatal Especializado o certificado por el Instituto Hondureño de la Niñez y la Familia (IHNFA), se ajustará a las reglas especiales siguientes:

a) Cuando la edad del infractor oscile entre dieciséis (16) y los dieciocho (18) años no cumplidos, la privación de libertad no podrá ser inferior a seis (6) meses ni exceder los ocho (8) años; b) Cuando la edad del infractor oscile entre catorce (14) y quince (15) años, la privación de libertad no podrá ser inferior a cuatro (4) meses ni exceder los cinco (5) años; y, c) Cuando la edad del infractor oscile entre doce (12) y trece (13) años, la privación de libertad no podrá ser inferior a un.(1) mes ni superior a tres (3) años.

El cumplimiento de esta Sanción se llevará a cabo de acuerdo al régimen que el Juez señale, tomando en cuenta

sus circunstancias personales, familiares, sociales y educativas. Para la individualización de la sanción, el Juez, deberá considerar el período de Detención Cautelar al que hubiera sido sometido.','205','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":218,"article_sha256":"75fb673861cba6e9ba8c4d876957565acfedd67bc5ba4bf2e753bc7ade2a3b5f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','205','ff606f1c701dfc095f8ae09b77d1d8669a9406baad7178fb96297d1b6b65744d','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:214','mayalex_normativos','10_LEYES_REGLAMENTOS','Los Tribunales de Apelaciones, resolverán los recursos de apelación en esta materia, en el término territorial que les corresponda, conforme a lo dispuesto en el Código Procesal Penal y las disposiciones especiales previstas en este Título.

Mientras se crean estas instancias, la Corte de Apelaciones Ordinaria respectiva conocerá de la vía recursiva en esta materia, conforme a la competencia por razón del territorio.','214','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":227,"article_sha256":"126bd591829784aeff58534a0aa048948fb6891ef9833cc707bcd79a6f8b9211","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','214','a688582588113bd33d05f3991bfd54acf7de994254e773cc3064da720c440622','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:217','mayalex_normativos','10_LEYES_REGLAMENTOS','El representante del Ministerio Público deberá ejercer la acción penal en todos los casos en que sea procedente, con arreglo a las disposiciones de este Código. No obstante, podrá solicitar que se prescinda, total

o parcialmente de la persecución penal, que se limite a alguno o a varios hechos o a solamente alguno de los Niños(as) que supuestamente participaron en su realización, en los casos siguientes:

a) Cuando la pena aplicable al Hecho Delictivo no exceda de cinco (5) años, la afectación del interés público sea mínima y, de los antecedentes y circunstancias personales de los Niños(as), se infiera su falta de peligrosidad; b) Se trate de un hecho insignificante, de mínima culpabilidad del supuesto autor o partícipe o ínfima contribución de éste, salvo que afecte seriamente un interés público; c) El Niño(a) haya sufrido a consecuencia del hecho, grave daño físico o psíquico que torne desproporcionada la aplicación de una Sanción o cuando en ocasión de una infracción culposa haya sufrido un daño moral de difícil superación; d) El Niño(a), hubiera hecho cuanto estaba a su alcance para impedir los efectos de la consumación del Hecho Delictivo; e) Cuando la pena a aplicar por un delito, sea de menor importancia, en comparación con la que se le impuso o se le debe imponer a la misma persona por otro Hecho delictivo conexo; y, f) Cuando se trate de Hechos Delictivos de delincuencia organizada, criminalidad violenta protagonizada por grupos o bandas de delincuentes, otros delitos graves de realización compleja que dificulte su investigación y persecución, y colabore eficazmente con la investigación, brinde información especial para evitar que continúe el Hecho Delictivo o se perpetren otros o ayude a esclarecer el hecho investigado u otros conexos o proporcione información útil para probar la participación de terceras personas, siempre que la acción penal de la cual se trate resulte más leve que los hechos punibles cuya persecución facilite o cuya continuación evite.

El Fiscal del caso deberá aplicar el Criterio de Oportunidad sobre la base de razones objetivas y sin discriminación, valorando las pautas descritas en cada caso individual, salvo en el supuesto contemplado por el inciso f) donde se procederá conforme las reglas generales que al efecto haya dictado el Ministerio Público.

El Ministerio Público velará que el daño causado sea razonablemente reparado.

Para la tramitación del Criterio de Oportunidad, se estará a lo dispuesto en el Código Procesal Penal.','217','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":230,"article_sha256":"1996af82c32585c9d961e163521fba29f0c64e85e9d0d704acbff53f75be946f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','217','a8207cc1a4542acd3b7ca299c0a95cc2b0c01c510dcf7f9315245c80fa33dab6','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:223','mayalex_normativos','10_LEYES_REGLAMENTOS','Ante el incumplimiento injustificado del plan de reparación o las reglas impuestas, de oficio o a petición de parte, el Juez llamará a una audiencia en la que se resolverá fundada y motivadamente sobre la revocación de la Suspensión del Proceso a Prueba.

Si mediara justificación válida, podrá reprogramar el plazo con la finalidad de asegurar el cumplimiento del término decretado, no obstante, esta no excederá los tres (3) meses adicionales, y solo podrá concederse por una vez.','223','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":236,"article_sha256":"2e4be41e7a977a913153fc3198097894bbcddcfdc8726e4932d54693ebf29e0c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','223','0184dbb7013a470b016e694c851dad924c7cf74cc303b982a6de4232d432d2a5','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:225','mayalex_normativos','10_LEYES_REGLAMENTOS','Los efectos de la Suspensión del Proceso a Prueba cesarán mientras El Niño(a) esté privado de su libertad por otro Proceso, pero si goza de libertad, el plazo seguirá su curso, no obstante no podrá decretarse la extinción de la acción penal sino cuando quede firme la resolución que lo exime de responsabilidad por el nuevo hecho.

La revocatoria de la Suspensión del Proceso a Prueba no impedirá el pronunciamiento de una sentencia absolutoria ni la concesión de algunas de las medidas sustitutivas a la privación de libertad, cuando fueren procedentes.','225','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":238,"article_sha256":"441f34e2f2f0c4c5a6bff32e00103f28bac5ec4979f7cc2ef2d823e135e6c810","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','225','608cf5ee910dec33f98e4465dd6c4068876effe4ce468e9bdf8ffa7860402baf','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:227','mayalex_normativos','10_LEYES_REGLAMENTOS','El Proceso Para la Niñez Infractora de Ley, estará compuesto por las fases siguientes:

a) Preparatoria; b) Intermedia; y, c) Juicio.

La Fase Preparatoria comprenderá los actos siguientes:

a) Denuncia; b) Investigación; c) Acusación; y, d) Vinculación al proceso.

La Fase Intermedia comprenderá los actos siguientes:

a) Interposición de incidentes, excepciones y nulidades; b) Formalización de la acusación y contestación de cargos; y, c) Auto de apertura a Debate.

La Fase de Juicio integra los actos siguientes:

a) Preparación del Debate; b) Audiencia de Debate; c) Individualización de la Sanción; y, d) Sentencia.','227','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":240,"article_sha256":"876a83c2f939931f88e56060717bb2e56f4116af4919ffeb850d2467a8798bbb","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','227','5161c70a5bb9c9ebedd8dcb6ec953b5bb59eb8949fb2e960d3c513f9503d942f','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:234','mayalex_normativos','10_LEYES_REGLAMENTOS','La Fase de Juicio integra los actos siguientes:

a) Preparación del Debate; b) Audiencia de Debate; c) Individualización de la Sanción; y, d) Sentencia.','234','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":247,"article_sha256":"a5f25f9571a1a60f2f38804367aa919399c7595103faf11a9c811d7dbbc8295d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','234','675eb3b36079f8d50a2a90e36ffe4cf67491cd38f1e4707939434306789d8d71','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:238','mayalex_normativos','10_LEYES_REGLAMENTOS','En la Audiencia de Lectura de Sentencia estarán presentes las partes, El Niño(a), sus representantes legales o en su caso, el representante del Instituto Hondureño de la Niñez y la Familia (IHNFA).

En esta audiencia, el Juez explicará con especial atención al Sancionado, las motivaciones de la imposición, las características generales de la Ejecución y las consecuencias de su incumplimiento.

La Sentencia será dictada en nombre del Estado de Honduras y deberá contener los requisitos siguientes:

a) El nombre y la ubicación del Juzgado de Letras de la Niñez o el que haga sus veces que dicte la resolución y la fecha de la misma; b) Nombre de las partes intervinientes; c) Los datos personales de El Niño (a) y cualquier otro dato de identificación relevante; d) El razonamiento y la decisión del Juez sobre cada una de las cuestiones planteadas durante el juicio, con exposición expresa de los motivos de hecho y de derecho en que se basa; e) La determinación precisa del hecho o hechos que el Juez tenga por probado; f) En su caso, deberá determinarse en forma clara, precisa y fundamentada la Sanción impuesta y su duración; S) El lugar de Ejecución de la Sanción, debiendo notificar al ente estatal encargado para ejecutar la o las mismas; h) El destino de las piezas de convicción, instrumentos y efectos del Hecho Delictivo; e, i) La firma del Juez y el Secretario.','238','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":251,"article_sha256":"287148501355042d265124be7be803d477e48ece58cc1108a34964cf12e2473e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','238','acd80e7009c9020f4ec5d9a8235c0ab7503282bb5178c1465be7c0199c1ce420','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:264','mayalex_normativos','10_LEYES_REGLAMENTOS','La Corte Suprema de Justicia distribuirá las funciones de los Jueces de Garantías, de Juicio y de Ejecución, de conformidad a lo establecido en este Código, debiéndoles dotar de los recursos presupuestarios, materiales, personal y logística necesarios.

No obstante, su creación será progresiva, de conformidad a los programas, planes y presupuestos de que disponga.

En tanto no se creen, distribuirá las responsabilidades de éstos, de manera que funcionen de conformidad con los Principios Rectores y la debida separación de funciones entre la instrucción, el Juzgamiento y Ejecución.','264','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":277,"article_sha256":"8730abded29baf4298b7dbe6d942382b4e722045bf06e0dbc0deb1568ba8a4a5","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_V8_D3","fuente_canonica":"V8_LA_GACETA_33222"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','264','3f7ef7708384ee20007ac5b7140d8bed398449299a4c96b7c062033a52167180','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:270','mayalex_normativos','10_LEYES_REGLAMENTOS','El Instituto Hondureño de la Niñez y la Familia creará y fomentará servicios:

a) Socio-educativos para niños infractores de la ley penal con personal capacitado en el área social, pedagógica, psicológica y legal;

b) Para niños amenazados o privados de sus derechos que estén en proceso de encontrar un hogar; y, c) Sociales, psicológicos, psiquiátricos y otros especiales que se consideren necesarios para apoyar el sano desarrollo de la niñez.','270','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":283,"article_sha256":"46c3ff8b64ead2da2c84ed3e7631ab0f1d40e315d87f359693e3b5b4a974e004","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','270','b8fee3cfbd6522df2b8c58743dddd6d2bd4d8bda3d48d54c4c9ab6b435505517','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:271','mayalex_normativos','10_LEYES_REGLAMENTOS','Las consejerías de familia u otras entidades análogas que cree el Estado y los centros de bienestar social y de seguridad pública serán organismos ejecutivos de las cuestiones de su competencia.','271','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":284,"article_sha256":"a82e1947bc4478f33a746eb04fb9b43afbda0cfe80914a1cbea3b21dc094ff4a","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','271','3ed4b71ea46f4914165727064ca39a63e188a0e800b21620a5c1f7e2e36aceb7','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:272','mayalex_normativos','10_LEYES_REGLAMENTOS','Las entidades privadas autorizadas por el Estado para prestarle servicios a la niñez podrán, previo acuerdo con los organismos públicos, ejecutar políticas nacionales vinculadas con los niños en cuestiones médicas, psicológicas, psiquiátricas, sociales, legales y demás análogas. Podrán, asimismo, administrar fondos públicos.','272','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":285,"article_sha256":"682f9d456723b74b8b71a104259072470f8401f50d404bc37e4d65b4473e3053","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','272','cdfd2a4bd97d2e67293ca60efd3ff076d4b2ae3f5afed687f7d1e1abd471e5bf','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:277','mayalex_normativos','10_LEYES_REGLAMENTOS','Los Juzgados de Letras de la Niñez serán los organismos encargados de conocer de todos los asuntos relacionados con niños infractores, así como de los casos en que sea necesario restituirle a un niño sus derechos conculcados.

Tales Juzgados sustituirán a los Juzgados de Letras de Menores a la fecha existentes.','277','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":290,"article_sha256":"e46fb9f3be2f937ff24ebeb4cc34ff8c34dfe012a23ee984e86bc3c6207fef83","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','277','6dcc5df5337950f944a3bc02b0da37672bb86ddbb81b09cf0ec0e5dbf436fca4','A03_CODIGO_NINEZ_01',now()),
('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:286','mayalex_normativos','10_LEYES_REGLAMENTOS','Reformase el numeral 3 del Artículo 180 del Código de la Familia, que en lo sucesivo se leerá así:

“Artículo 180. La inscripción de la adopción, además de las indicaciones comunes a toda inscripción, deberá contener: 1)...; 2)...; y, 3) Referencia a la resolución en que se autoriza la adopción".','286','Código de la Niñez y de la Adolescencia (Decreto 73-96), texto canónico v2 con las reformas del Decreto 35-2013 (La Gaceta 33,222)','{"texto_origen":"CANONICO_D3_FUENTES_MIXTAS","transcripcion_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","text_sha256":"99d911ac26acbdce3f3f0fc1af6e1162de32e3573ce5d791863f53a4b7219d36","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores, propietario_despacho (CLO / Director Maya Lex), firma D3 del 2026-11-18 sobre la v2 de HN:CODIGO_NINEZ (ADJUDICACION_CLO_CODIGO_NINEZ.md §3)","manifiesto_sha256":"bd4d067d1ff2980db99a7527d21f9f381d996bb0a2d63933e30f7bcaecb2d372","pliego":"docs/corpus/staging/2026-11-04-hn-001-tranche-a-drive/canonico-v2/ADJUDICACION_CLO_CODIGO_NINEZ.md","procedencia":"Fuentes mixtas acreditadas por el pliego D1–D8 firmado (ver estado_canonico de cada fila); sin V4/V5 hasta el SQL de visibilidad","norm_id":"HN:CODIGO_NINEZ","instrumento_id":"CODIGO_NINEZ","ingest_batch":"A03_CODIGO_NINEZ_01","ordinal":300,"article_sha256":"a1d6efa9c4fe5b1eb020d31b63bb6db5204324141283fef70cd99c957f621371","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[],"estado_canonico":"TEXTO_A03_DICTAMINADO_CLO","fuente_canonica":"A03_CONSOLIDADO_DICTAMINADO"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_NINEZ','286','82bbf79338b4df3c129d07e25938eecbea9874e56371afa95aacd38f799f90f0','A03_CODIGO_NINEZ_01',now()),
('A04_D35_2013_01:DECRETO_35_2013:6','mayalex_normativos','10_LEYES_REGLAMENTOS','Reformar los Artículos 37,234,271,434,
511,516,559,960,963,972 y 973 del CÓDIGO CIVIL emitido
mediante Decreto Ejecutivo No.76 de 19 de Enero de 1906, los
cuales se leerán así:

"ARTÍCULO 37.- En los casos en que la Ley dispone que
se oiga a los(as) parientes de una persona, se entenderán
comprendidos(as) en esa denominación su cónyuge o
compañero(a) de hogar en una unión de hecho debidamente
reconocida, sus consanguíneos de uno u otro sexo mayores de
edad. A falta de consanguíneos en suficiente número, serán oídos
sus parientes por afinidad.

Serán preferidos(as) los y las descendientes y ascendientes a
los colaterales, y entre éstos, a los de más cercano parentesco.

Los(as) parientes serán citados y comparecerán a ser oídos
verbalmente, en la forma prescrita por el Código Procesal Civil."

"ARTÍCULO 234.- Los derechos concedidos a los padres
en los artículos precedentes, no podrán reclamarse sobre el

hijo(a) que haya sido llevado por ellos a un hogar de
protección o abandonado(a) de otra manera."

"ARTÍCULO 271.- No pueden obtener habilitación de
edad por el(la) Juez(a), los(las) hijos(as) menores de
dieciocho (18) años aunque hayan sido emancipados(as)."

"ARTÍCULO 434.- Los padres no obstante lo dispuesto
en los artículos 430 y 431, y cualquier otra persona, podrán
nombrar guardador(a) por testamento o por actos entre
vivos, con tal que donen o dejen al(la) pupilo(a) alguna parte
de sus bienes.

Esta guarda se limitará a los bienes que se donen o se dejen
al(la)pupilo(a)."

"ARTÍCULO 511.- Los padres, o el(la) tutor(a) al llegar
el(la) demente a la mayoría de edad, deberán provocar el
juicio de interdicción."

"ARTÍCULO 516.- Serán nombrados guardadores del(la)
demente o enfermo(a) mental:

1) Su cónyuge o compañero(a) de hogar en unión de
hecho debidamente reconocida;
2) Sus descendientes;
3) Sus ascendientes;
4) Sus hermanos; y,
5) Sus colaterales hasta el tercer grado.

El (la) Juez(a) elegirá entre las personas comprendidas en
cada uno de los numerales 2), 3), 4) y 5), la persona que
más idónea le parezca.

A falta de las personas indicadas, se nombrará a personas
que no tengan ningún parentesco.

No puede ser nombrado(a) guardador(a) quien por sus actos
criminales o puramente reprensibles practicados en perjuicio
de el(la) interdicto(a), hubiese causado la demencia de
éste(a)."

"ARTÍCULO 559.- Si es deferida una tutela o curaduría al
ascendiente o descendiente que no ha cumplido veintiún (21)
años, se aguardará a que los cumpla para deferirle el cargo,
y se nombrará un(a) interino(a) para el tiempo intermedio.

Se aguardará de la misma manera al(la) tutor(a) o curador(a)
testamentario(a) que no haya cumplido veintiún (21) años.
No obstante será inválido el nombramiento de tutor(a) o
curador(a) menor, cuando llegando a los veintiún (21) años
sólo tendría que ejercer la tutela o curaduría por menos de
(1) año."

"ARTÍCULO 960.- Son llamados a la sucesión intestada: .

1) Los(as) descendientes de el(la) difunto(a);
2) El(la) cónyuge o compañero(a) de hogar en unión de
hecho debidamente legalizada sobreviviente;
3) Sus ascendientes;
4) Sus colaterales; y,
5) El municipio donde el(la) causante tuvo su último
domicilio."

"ARTÍCULO 963.- Hay siempre lugar a la representación:

1) En la descendencia del difunto de cuya sucesión se
trata;
2) En la descendencia de sus hermanos; y,
3) En la descendencia de sus hijos o nietos.

Fuera de estas descendencias no hay lugar a la
representación."

"ARTÍCULO 972.- A falta del cónyuge o compañero(a)
de hogar en unión de hecho debidamente reconocida
sobreviviente, descendientes, ascendientes y hermanos,
sucederán al(la) difunto(a) los otros colaterales, según las
reglas siguientes:

1) El(la) colateral o los(as) colaterales del grado más
próximo, excluirán siempre a los(as) otros(as). Entre
estos(as) colaterales no hay representación;
2) Los derechos de sucesión de los(as) colaterales no
se extienden más allá del sexto grado; y,
3) Los colaterales de simple conjunción, esto es, los que
sólo son parientes de el(la) difunto(a) por parte de
padre o por parte de madre, gozan de los mismos
derechos que los colaterales de doble conjunción."

ARTÍCULO 973.- A falta de todos(as) los(as) herederos
ab intestato, sucederá el municipio en que el causante haya
tenido su último domicilio."

